// jsonfmt: reads one JSON document from stdin, checks it, and pretty-prints it.

fn main() ! io, fail {
  let src = os.read_stdin()?
  let out = format(src)?
  print(out)
}

// The kind of container a parser is inside.
enum Ctx {
  Arr
  Obj
}

// What the parser expects next.
enum Step {
  Value
  Key
  After
  Done
}

// Parser state: the input, the position of the next byte, the output so far,
// and the containers that are open. It uses no recursion, so deep nesting is fine.
type Parser { src: str, i: int, out: str, stack: [Ctx] }

// `src` pretty-printed with two-space indents, without a final newline. Fails
// with `.Invalid` and "line L, column C: ..." at the first byte that can't
// continue a valid document.
fn format(src: str) -> str ! fail
  ex format("42") == "42"
  ex format("[1, {}]") == "[\n  1,\n  {}\n]"
  ex format("{\"a\" : [ ]}") == "{\n  \"a\": []\n}"
  ex format("[1,]") fails .Invalid
  ex format("") fails .Invalid
{
  var p = Parser(src, i: 0, out: "", stack: [])
  var step = Step.Value
  while step != .Done {
    p.skip_ws()
    step = match step {
      .Value => p.value()?
      .Key => p.key()?
      .After => p.after()?
      .Done => Step.Done
    }
  }
  if p.i != src.len() {
    p.bad("expected the end of the input")?
  }
  return p.out
}

// The byte at the current position, or 0 at the end of the input. A real 0
// byte is never valid, so both fail at the same place.
fn Parser.peek(self) -> u8 {
  if self.i < self.src.len() {
    return self.src[self.i]
  }
  return 0
}

fn Parser.skip_ws(inout self) {
  while self.i < self.src.len() && _is_ws(self.src[self.i]) {
    self.i += 1
  }
}

fn _is_ws(c: u8) -> bool {
  return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

fn _is_hex(c: u8) -> bool {
  return c.is_digit() || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

// Two spaces for each open container.
fn Parser.pad(self) -> str {
  return "  ".repeat(self.stack.len())
}

// Fails with the line and column of the current position.
fn Parser.bad(self, what: str) -> never ! fail {
  var line = 1
  var col = 1
  for k in 0..self.i {
    if self.src[k] == '\n' {
      line += 1
      col = 1
    } else {
      col += 1
    }
  }
  fail(.Invalid, "line ${line}, column ${col}: ${what}")
}

// Parses a scalar, or opens a container.
fn Parser.value(inout self) -> Step ! fail {
  let c = self.peek()
  if c == '{' {
    self.i += 1
    self.skip_ws()
    if self.peek() == '}' {
      self.i += 1
      self.out += "{}"
      return .After
    }
    self.stack.push(.Obj)
    self.out += "{\n"
    return .Key
  }
  if c == '[' {
    self.i += 1
    self.skip_ws()
    if self.peek() == ']' {
      self.i += 1
      self.out += "[]"
      return .After
    }
    self.stack.push(.Arr)
    self.out += "[\n" + self.pad()
    return .Value
  }
  if c == '"' {
    self.string()?
  } else if c == '-' || c.is_digit() {
    self.number()?
  } else if c == 't' {
    self.literal("true")?
  } else if c == 'f' {
    self.literal("false")?
  } else if c == 'n' {
    self.literal("null")?
  } else {
    self.bad("expected a value")?
  }
  return .After
}

// Parses an object key and its colon.
fn Parser.key(inout self) -> Step ! fail {
  if self.peek() != '"' {
    self.bad("expected a string key")?
  }
  self.out += self.pad()
  self.string()?
  self.skip_ws()
  if self.peek() != ':' {
    self.bad("expected ':'")?
  }
  self.i += 1
  self.out += ": "
  return .Value
}

// Handles what follows a complete value: a comma, a closing bracket, or the end.
fn Parser.after(inout self) -> Step ! fail {
  let top = self.stack.last() else {
    return .Done
  }
  let c = self.peek()
  return match top {
    .Arr => self.after_in(c, close: ']', next: .Value)?
    .Obj => self.after_in(c, close: '}', next: .Key)?
  }
}

fn Parser.after_in(inout self, c: u8, close: u8, next: Step) -> Step ! fail {
  if c == ',' {
    self.i += 1
    self.out += ",\n"
    if next == .Value {
      self.out += self.pad()
    }
    return next
  }
  if c != close {
    if close == ']' {
      self.bad("expected ',' or ']'")?
    }
    self.bad("expected ',' or '}'")?
  }
  self.i += 1
  _ = self.stack.pop()
  self.out += "\n" + self.pad()
  self.out += if close == ']' { "]" } else { "}" }
  return .After
}

// Copies a string verbatim, checking its escapes.
fn Parser.string(inout self) ! fail {
  let start = self.i
  self.i += 1
  while true {
    let c = self.peek()
    if c < 0x20 {
      self.bad("unterminated string or raw control character")?
    }
    self.i += 1
    if c == '"' {
      break
    }
    if c == '\\' {
      let e = self.peek()
      if !(e == '"' || e == '\\' || e == '/' || e == 'b' || e == 'f' || e == 'n' ||
          e == 'r' || e == 't' || e == 'u') {
        self.bad("invalid escape")?
      }
      self.i += 1
      if e == 'u' {
        for _ in 0..4 {
          if !_is_hex(self.peek()) {
            self.bad("expected a hex digit")?
          }
          self.i += 1
        }
      }
    }
  }
  self.out += self.src[start..self.i]
}

// Copies a number verbatim, checking its form.
fn Parser.number(inout self) ! fail {
  let start = self.i
  if self.peek() == '-' {
    self.i += 1
  }
  if self.peek() == '0' {
    self.i += 1
  } else {
    self.digits()?
  }
  if self.peek() == '.' {
    self.i += 1
    self.digits()?
  }
  if self.peek() == 'e' || self.peek() == 'E' {
    self.i += 1
    if self.peek() == '+' || self.peek() == '-' {
      self.i += 1
    }
    self.digits()?
  }
  self.out += self.src[start..self.i]
}

// One or more digits.
fn Parser.digits(inout self) ! fail {
  if !self.peek().is_digit() {
    self.bad("expected a digit")?
  }
  while self.peek().is_digit() {
    self.i += 1
  }
}

fn Parser.literal(inout self, word: str) ! fail {
  for k in 0..word.len() {
    if self.peek() != word[k] {
      self.bad("expected '${word}'")?
    }
    self.i += 1
  }
  self.out += word
}
